import {garmentSwatches,garmentSizes,garmentPhoto,apparelConfigMarkup} from './apparel-ui.mjs';
import {DICT} from '/studio/i18n.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/* ---- turnaround (text only; no rush selector) ---- */
export function turnaroundText(rule){if(typeof rule?.turnaround==='string'&&rule.turnaround)return rule.turnaround;const p=String(rule?.path||'');return p.includes('/print-shop/large-format/')?'2–5 business days':p.includes('/print-shop/')?'7–10 business days':'';}
/* ---- label options: shape cards with icons, one-row size ---- */
const SHAPE_ICONS={rect:'<rect x="5" y="11" width="30" height="18" rx="1.5"/>',rounded:'<rect x="5" y="11" width="30" height="18" rx="6"/>',square:'<rect x="9" y="9" width="22" height="22" rx="1.5"/>',circle:'<circle cx="20" cy="20" r="12"/>',oval:'<ellipse cx="20" cy="20" rx="15" ry="10"/>',custom:'<path d="M20 6c3 0 4 4 7 5s7-1 8 2-3 5-3 8 4 5 2 8-6 1-8 3-2 6-6 6-3-5-6-6-7 1-8-2 3-5 2-8-5-4-3-7 6-1 8-3 4-6 7-6z" stroke-dasharray="3 2.4"/>'};
export function shapeKind(label){const l=String(label||'').toLowerCase();return /custom|die-cut|kiss-cut|contour/.test(l)?'custom':/round/.test(l)?'rounded':/square/.test(l)?'square':/circle/.test(l)?'circle':/oval/.test(l)?'oval':'rect';}
export const shapeIcon=label=>`<svg class="shape-icon" viewBox="0 0 40 40" width="40" height="40" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round" aria-hidden="true">${SHAPE_ICONS[shapeKind(label)]}</svg>`;
const isLabelRule=rule=>rule.pricingVersion==='supplier-labels';
/* ---- "Need a designer" contact block (email + WhatsApp), shared by every product page with a designer option ---- */
export const DESIGN_EMAIL='info@satingraphic.ca',DEFAULT_WHATSAPP='14163589740';
let waNumber=null;
/** WhatsApp number from Admin → Chat settings (public chat config), falling back to the shop's design line. */
export function whatsappNumber(){return waNumber??=fetch('/api/chat/config').then(r=>r.ok?r.json():{}).then(c=>String(c?.whatsapp||'').replace(/\D+/g,'')||DEFAULT_WHATSAPP).catch(()=>DEFAULT_WHATSAPP);}
export function whatsappLink(number,productName,pageURL=(typeof location!=='undefined'?location.origin+location.pathname:'')){const text=`Hi Satin Graphic, I'm on your website (${productName?productName+' page':'product page'}: ${pageURL}) and I'd like help with a design.`;return `https://wa.me/${String(number||DEFAULT_WHATSAPP).replace(/\D+/g,'')}?text=${encodeURIComponent(text)}`;}
const WA_ICON='<svg class="wa-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true"><path fill="currentColor" d="M17.47 14.38c-.3-.15-1.76-.87-2.03-.97-.27-.1-.47-.15-.67.15-.2.3-.77.97-.94 1.17-.17.2-.35.22-.65.07-.3-.15-1.26-.46-2.4-1.48-.89-.79-1.49-1.77-1.66-2.07-.17-.3-.02-.46.13-.61.13-.13.3-.35.45-.52.15-.17.2-.3.3-.5.1-.2.05-.37-.02-.52-.07-.15-.67-1.62-.92-2.22-.24-.58-.49-.5-.67-.51h-.57c-.2 0-.52.07-.79.37-.27.3-1.04 1.02-1.04 2.48s1.07 2.88 1.21 3.08c.15.2 2.1 3.2 5.08 4.49.71.31 1.26.49 1.69.63.71.23 1.36.2 1.87.12.57-.09 1.76-.72 2.01-1.41.25-.69.25-1.29.17-1.41-.07-.12-.27-.2-.57-.35M12.05 21.5h-.01a9.4 9.4 0 0 1-4.8-1.32l-.34-.2-3.57.94.95-3.48-.22-.36a9.43 9.43 0 0 1-1.44-5.02c0-5.2 4.24-9.44 9.45-9.44 2.52 0 4.89.98 6.67 2.77a9.37 9.37 0 0 1 2.76 6.68c0 5.2-4.24 9.44-9.45 9.44m8.04-17.48A11.3 11.3 0 0 0 12.05.7C5.78.7.68 5.8.68 12.06c0 2 .52 3.96 1.52 5.68L.58 23.3l5.7-1.5a11.33 11.33 0 0 0 5.77 1.47h.01c6.26 0 11.36-5.1 11.37-11.37 0-3.04-1.18-5.89-3.33-8.04"/></svg>';
export function designContactHTML(productName,number=DEFAULT_WHATSAPP){return `<div class="design-contact" data-design-contact><p class="design-contact-lead"><strong>For design you can contact us at the email address below</strong></p><p class="design-contact-email"><a href="mailto:${DESIGN_EMAIL}"><strong data-no-translate>${DESIGN_EMAIL}</strong></a></p><a class="wa-btn" data-wa-link href="${esc(whatsappLink(number,productName))}" target="_blank" rel="noopener">${WA_ICON}<span>You can also connect on WhatsApp</span></a></div>`;}
/** Shows (or hides) the designer contact block right after `anchor`; the WhatsApp link names the product page. */
export function syncDesignContact(anchor,productName,visible){if(!anchor?.isConnected)return null;let el=anchor.parentElement?.querySelector(':scope > [data-design-contact]');if(!visible){if(el)el.hidden=true;return el;}if(!el){const tmp=document.createElement('div');tmp.innerHTML=designContactHTML(productName);el=tmp.firstElementChild;anchor.after(el);whatsappNumber().then(n=>{const a=el.querySelector('[data-wa-link]');if(a)a.href=whatsappLink(n,productName);});}el.hidden=false;return el;}
const EXTRA_DICT={'Turnaround':{fa:'زمان تحویل',fr:'Délai de production',es:'Plazo de entrega'},'7–10 business days':{fa:'۷ تا ۱۰ روز کاری',fr:'7 à 10 jours ouvrables',es:'7–10 días hábiles'},'2–5 business days':{fa:'۲ تا ۵ روز کاری',fr:'2 à 5 jours ouvrables',es:'2–5 días hábiles'},'Size (inches)':{fa:'اندازه (اینچ)',fr:'Format (pouces)',es:'Tamaño (pulgadas)'},'Width':{fa:'عرض',fr:'Largeur',es:'Ancho'},'Height':{fa:'ارتفاع',fr:'Hauteur',es:'Alto'},'Ink':{fa:'جوهر',fr:'Encre',es:'Tinta'},'Oval':{fa:'بیضی',fr:'Ovale',es:'Óvalo'},'Square':{fa:'مربع',fr:'Carré',es:'Cuadrado'},'Rounded rectangle':{fa:'مستطیل گوشه‌گرد',fr:'Rectangle arrondi',es:'Rectángulo redondeado'},'Custom die-cut shape':{fa:'برش سفارشی (دای‌کات)',fr:'Forme découpée sur mesure',es:'Forma troquelada personalizada'},'White Gloss BOPP':{fa:'BOPP سفید براق',fr:'BOPP blanc brillant',es:'BOPP blanco brillante'},'Clear BOPP':{fa:'BOPP شفاف',fr:'BOPP transparent',es:'BOPP transparente'},'White Paper':{fa:'کاغذ سفید',fr:'Papier blanc',es:'Papel blanco'},'Full colour (CMYK)':{fa:'تمام‌رنگی (CMYK)',fr:'Quadrichromie (CMJN)',es:'A todo color (CMYK)'},'Full colour + white ink (for clear film)':{fa:'تمام‌رنگی + جوهر سفید (برای فیلم شفاف)',fr:'Quadrichromie + encre blanche (film transparent)',es:'A todo color + tinta blanca (para film transparente)'},'White ink is only available on Clear BOPP.':{fa:'جوهر سفید فقط روی BOPP شفاف در دسترس است.',fr:'L’encre blanche est offerte sur BOPP transparent seulement.',es:'La tinta blanca solo está disponible en BOPP transparente.'},'For design you can contact us at the email address below':{fa:'برای طراحی می‌توانید از طریق ایمیل زیر با ما در تماس باشید',fr:'Pour le design, écrivez-nous à l’adresse ci-dessous',es:'Para el diseño, contáctanos en el correo de abajo'},'You can also connect on WhatsApp':{fa:'همچنین می‌توانید در واتس‌اپ با ما در ارتباط باشید',fr:'Vous pouvez aussi nous joindre sur WhatsApp',es:'También puedes escribirnos por WhatsApp'}};
for(const [k,v] of Object.entries(EXTRA_DICT))if(!DICT[k])DICT[k]=v;
export const referenceForm=r=>r.path.includes('/vehicle-wraps/estimator/')||r.id.startsWith('glass-')||r.id==='window-graphics'||r.id==='tint-commercial'||r.id==='wallpaper'||r.id.startsWith('wallpaper-');
export const designFee=r=>Number(r.constants.designFee??r.constants.designDeposit??250);
const descriptions={'Decals + Lettering':'Essential branding for doors, sides and rear.','Partial Wrap':'Strategic printed coverage with strong visual impact.','Half / ¾ Wrap':'More coverage while balancing budget and visibility.','Full Wrap':'Maximum brand presence across the vehicle body.'};
export const estimatorImages={sedan:['sedan-bare','dec-sedan','sedan-wrapped'],suv:['suv-full-bare','dec-suv-full','suv-full-wrapped'],'pickup-truck':['pickup-bare','dec-pickup','pickup-wrapped'],minivan:['van-bare','dec-smallvan','van-wrapped'],'transit-van':['transit-bare','transit-wrapped','transit-wrapped'],'sprinter-van':['sprinter-bare','dec-sprinter','sprinter-wrapped'],'cargo-van':['van-bare','dec-sprinter','van-wrapped'],trailer:['trailer-bare','trailer-decal','trailer-wrapped'],'box-truck':['box-truck-bare','box-truck-decal','box-truck-wrapped'],bus:['bus-bare','bus-decal','bus-wrapped']};
export function artworkHTML(r,studio=false){if(r.id==='design-services')return '<section class="rule-artwork"><h4>Share a document or sample (optional)</h4><div data-art-controls></div><div data-art-preview></div><p data-art-status role="status"></p></section>';return `<section class="rule-artwork"><h4>Your artwork${r.artworkOptional?' <span class="tiny">(optional)</span>':''}</h4>${r.artworkOptional?'<p class="small">Uploading a file is optional — order the pattern as shown, or send your own image or a photo of your wall.</p>':''}<div class="artwork-options"><label><input type="radio" name="artwork-mode" value="upload" checked>Upload ready artwork</label>${r.artworkOptional?'':`<label><input type="radio" name="artwork-mode" value="designer">I need a designer <span class="tiny">+$${designFee(r)}</span></label>`}${studio&&!r.path.includes('/vehicle-wraps/estimator/')?'<label><input type="radio" name="artwork-mode" value="studio">Design it myself</label>':''}</div><p class="small"><a href="/satin/design-agreement/" target="_blank" rel="noopener">Read Design Policy</a></p><div data-art-controls><input type="file" data-art-upload accept="image/png,image/jpeg,image/webp,application/pdf"><p class="small">PNG, JPG, WebP or PDF · maximum 20 MB</p></div><div data-art-preview></div><p data-art-status role="status"></p></section>`;}
function options(f,v,wrap){const list=f.type==='checkbox'?[{label:'No',value:0},{label:'Yes',value:1}]:f.options;const cards=f.key==='coverage'&&wrap;return `<fieldset class="og reference-option ${cards?'coverage-cards':''}"><legend class="lab">${esc(f.key==='roof'?'Add roof wrap?':f.label)}</legend><div class="reference-choices">${list.map((o,i)=>`<label class="reference-choice"><input type="radio" name="option-${f.key}" data-rf="${f.key}" data-option-index="${i}" value="${o.value}" ${o.value===v?'checked':''}><span><strong>${esc(o.label)}</strong>${cards?`<small>${esc(descriptions[o.label]||'')}</small>`:''}${wrap&&['coverage','finish','material'].includes(f.key)?`<small>× ${Number(o.value).toFixed(2)}</small>`:f.key==='material'&&!wrap?`<small>$${o.value} / sq ft</small>`:''}</span></label>`).join('')}</div></fieldset>`;}
export function pricingMarkup(rule,configured,values){const wrap=rule.path.includes('/vehicle-wraps/estimator/'),glass=rule.id.startsWith('glass-')||rule.id==='window-graphics',fee=designFee(rule),img=estimatorImages[rule.id.slice(5)];const vehicleImage=i=>configured?.images?.length>=3?configured.images[i]:'/satin/img/'+img[i]+(/^(trailer|box-truck|bus)-/.test(img[i])?'.svg':'.png');const fields=rule.fields.filter(f=>f.key!=='design');const numbers=fields.filter(f=>f.type==='number'),choices=fields.filter(f=>f.type!=='number');const render=f=>options(f,values[f.key],wrap);const noArt=['glass-frosted-vinyl','tint-commercial','tint-vehicle'].includes(rule.id);
return `<div class="opts">${wrap&&img?`<div class="vehstage" data-reference-vehicle><img src="${vehicleImage(0)}" alt="${esc(rule.label)} before wrapping"><img data-ref-decal src="${vehicleImage(1)}" alt="Vehicle with decals" style="opacity:0"><img data-ref-wrap src="${vehicleImage(2)}" alt="Vehicle with full wrap"></div><p class="tiny" data-reference-caption>Preview updates with your wrap coverage.</p>`:''}${wrap?`<span class="eyebrow plain">01 / Your vehicle</span>${choices.filter(f=>f.key.startsWith('vehicle_')).map(render).join('')}<span class="eyebrow plain">02 / Your wrap</span>${['coverage','roof','finish','material'].map(k=>choices.find(f=>f.key===k)).filter(Boolean).map(render).join('')}`:`<span class="eyebrow plain">${glass?'Measure the glass':'Measure your wall'}</span><div class="fields reference-measurements">${numbers.map(f=>`<label class="field"><span class="lab">${esc(f.label)}</span><input class="inp" type="number" data-rf="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${values[f.key]}"></label>`).join('')}</div>${choices.map(render).join('')}`}${!noArt&&(rule.artworkOptional||rule.fields.some(f=>f.key==='design'))?artworkHTML(rule):''}</div><aside class="rule-summary summary"><div class="sum-body"><span class="eyebrow plain">${wrap?'Your estimate':'Estimated total'}</span><div class="product-order-total total" data-order-total></div><div class="product-order-choices lines" data-order-choices></div><p class="tiny">${wrap?'Starting price · CAD. Final pricing depends on the confirmed vehicle and scope.':'Measurements and installation scope are confirmed before production.'}</p><details class="sum-extras"><summary>Add notes / discount code</summary><label class="order-notes">Project notes <em>(optional)</em><textarea data-order-notes maxlength="1000" rows="3" placeholder="Deadline, colours, placement or anything we should know"></textarea></label><label class="small">Discount code<input class="inp" data-discount-code maxlength="40" placeholder="Optional code"></label><button class="btn ghost sm" data-apply-code>Apply code</button></details>${wrap?'<a class="btn ghost block sum-change" href="/satin/vehicle-wraps/estimator/">Change vehicle</a>':''}</div><div class="sum-foot"><div class="studio-price" data-rule-price></div><p data-price-error role="status"></p><button class="btn block" data-rule-add ${wrap||rule.id.startsWith('tint-')?'hidden':''}>${wrap?'Get exact quote':'Add to cart'}</button><button class="btn ghost block" data-quote="${wrap?'Vehicle Wraps':rule.id==='tint-commercial'?'Window Tint':glass?'Window Graphics':'Wallpaper'}">Get exact quote</button></div></aside>`;}
export function replaceConfig(html,replacement){const start=html.search(/<div\b[^>]*class="(?:cfg|rule-cfg)[^"]*"/);if(start<0)return html;const re=/<\/?div\b[^>]*>/g;re.lastIndex=start;let depth=0,m;while((m=re.exec(html))){depth+=m[0].startsWith('</')?-1:1;if(depth===0)return html.slice(0,start)+replacement+html.slice(re.lastIndex);}return html;}
export function choiceLines(rule,values,labels={}){const currency=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD',maximumFractionDigits:2}).format(n);const wrap=rule.path.includes('/vehicle-wraps/estimator/');const lines=[];if(wrap)lines.push(['Vehicle base',currency(rule.constants.base)]);for(const f of rule.fields){const v=values[f.key];if(f.key==='design'){if(v)lines.push(['Design services',currency(designFee(rule))]);continue;}const option=f.options?.find(o=>o.value===v);const selected=labels[f.key]??option?.label;if(wrap){if(f.key.startsWith('vehicle_')){if(v!==1)lines.push([f.label+': '+selected,'× '+v.toFixed(2)]);}else if(f.key==='roof'){if(v)lines.push(['Roof wrap','× '+rule.constants.roofMultiplier.toFixed(2)]);}else lines.push([selected+(f.key==='material'?' film':f.key==='finish'?' finish':''),'× '+v.toFixed(2)]);}else lines.push([f.label,f.type==='select'?selected:f.type==='checkbox'?(v?'Yes':'No'):String(v)]);}return lines.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('');}

const requiresAttr=o=>o?.requires?` data-requires="${esc(JSON.stringify(o.requires))}"`:'';
/** Label products: shape cards with icons; any rule: width + height of group "size" on one row. Null = default rendering. */
function specialField(rule,f,values){if(f.type==='number'&&f.group==='size'){const pair=rule.fields.filter(x=>x.type==='number'&&x.group==='size');if(pair.length!==2)return null;if(f!==pair[0])return '';const help=pair.map(x=>x.help).filter(Boolean).join(' ');return `<fieldset class="product-option-group size-pair"><legend>Size (inches)</legend><div class="size-row">${pair.map((x,i)=>`${i?'<span class="size-x" aria-hidden="true">×</span>':''}<label class="product-number-field"><span>${esc(String(x.label).replace(/\s*\((in|inches|ft|cm)\)\s*$/i,''))}</span><input type="number" inputmode="decimal" data-rf="${x.key}" min="${x.min}" max="${x.max}" step="${x.step}" value="${values[x.key]}"></label>`).join('')}</div>${help?`<p class="small size-help">${esc(help)}</p>`:''}</fieldset>`;}
 if(f.type==='select'&&f.key==='shape'&&isLabelRule(rule))return `<fieldset class="product-option-group shape-group"><legend>${esc(f.label)}</legend><div class="product-option-cards shape-cards">${f.options.map((o,index)=>`<label class="product-option-card shape-card" title="${esc(o.label)}"><input type="radio" name="option-${f.key}" data-rf="${f.key}" data-option-index="${index}" value="${o.value}" ${o.value===values[f.key]?'checked':''}><span class="product-option-content">${shapeIcon(o.label)}<strong>${esc(o.label)}</strong></span></label>`).join('')}</div></fieldset>`;
 return null;}
export function genericMarkup(rule,configured,values,product){if(rule.quantityKeys&&rule.fields.some(f=>f.key==='colour'))return apparelConfigMarkup(rule,configured,values,product,(product||configured?.artwork||rule.fields.some(f=>f.key==='design'))?artworkHTML(rule,!!product):'');return `<div>${configured?.images?.length&&!rule.quantityKeys?`<div class="managed-product-gallery">${(rule.quantityKeys?[garmentPhoto(rule.id,values.colour),...configured.images.slice(1)]:configured.images).map(src=>`<img src="${esc(src)}" alt="${esc(configured.name)}" loading="lazy">`).join('')}${configured.modelCaption?`<p class="small">${esc(configured.modelCaption)}</p>`:''}</div>`:''}${rule.quantityKeys?'':`<h3>${esc(configured?.name||rule.label)}</h3>`}${configured?.description&&!rule.quantityKeys?`<p class="managed-product-description">${esc(configured.description)}</p>`:''}<div class="rule-fields">${rule.quantityKeys?garmentSwatches(rule,values)+garmentSizes(rule,values):''}${[...rule.fields.filter(f=>f.key!=='quantity'&&f.key!=='design'&&(!rule.quantityKeys||f.key!=='colour'&&f.key!=='placement'&&!rule.quantityKeys.includes(f.key))),...rule.fields.filter(f=>f.key==='quantity'&&f.key!=='design')].map(f=>specialField(rule,f,values)??(f.type==='select'?`<fieldset class="product-option-group ${f.key==='card_collection'?'featured-options':''}"><legend>${esc(f.label)}</legend><div class="product-option-cards">${f.options.map((o,index)=>`<label class="product-option-card"${requiresAttr(o)}><input type="radio" name="option-${f.key}" data-rf="${f.key}" data-option-index="${index}" value="${o.value}" ${index===f.options.findIndex(o=>o.value===values[f.key])?'checked':''}><span class="product-option-content"><strong>${esc(o.label)}</strong></span></label>`).join('')}</div></fieldset>`:f.type==='checkbox'?`<label class="product-check-card"><input type="checkbox" data-rf="${f.key}" ${values[f.key]?'checked':''}><span>${esc(f.label)}</span></label>`:`<fieldset class="product-option-group"><legend>${esc(f.label)}</legend>${f.key==='quantity'&&!rule.path.includes('/large-format/')&&product?.quantity?.length?`<div class="quantity-presets">${product.quantity.filter(n=>n>=f.min&&n<=f.max).map(n=>`<button type="button" data-quantity="${n}" aria-pressed="${values[f.key]===n}">${n.toLocaleString('en-CA')}</button>`).join('')}</div>`:''}<label class="product-number-field"><span>${f.key==='quantity'&&!rule.path.includes('/large-format/')&&product?.quantity?.length?'Custom quantity':esc(f.label)}</span><input type="number" data-rf="${f.key}" min="${f.min}" max="${f.max}" step="${f.step}" value="${values[f.key]}"></label></fieldset>`)).join('')}</div>${(rule.id==='design-services'||product||configured?.artwork||rule.artworkOptional||rule.fields.some(f=>f.key==='design'))?artworkHTML(rule,!!product):''}</div><aside class="rule-summary"><div class="sum-body"><h3>Your order</h3><div class="product-order-total" data-order-total></div><div class="product-order-choices" data-order-choices></div>${turnaroundText(rule)?`<div class="order-turnaround" data-order-turnaround><span>Turnaround</span><strong>${esc(turnaroundText(rule))}</strong></div>`:''}<details class="sum-extras"><summary>Add notes / discount code</summary><label class="order-notes">Project notes <em>(optional)</em><textarea data-order-notes maxlength="1000" rows="3" placeholder="Deadline, colours, placement or anything we should know"></textarea></label><label>Discount code<input data-discount-code maxlength="40" placeholder="Optional code"></label><button class="btn ghost sm" data-apply-code style="margin-top:10px">Apply code</button></details>${rule.priceNote?`<p class="small product-price-note">${esc(rule.priceNote)}</p>`:''}</div><div class="sum-foot"><div class="studio-price" data-rule-price>Calculating…</div><p data-price-error role="status"></p><button class="btn block" data-rule-add style="margin-top:16px" ${rule.id.startsWith('ppf-')||rule.id==='tint-vehicle'?'hidden':''}>Add to cart</button><button class="btn ghost block" data-quote="${rule.id.startsWith('ppf-')?'Vehicle Wraps':rule.id.startsWith('tint-')?'Window Tint':rule.path.includes('/apparel')?'Apparel':rule.path.includes('/print-shop')?'Print Shop':'Shop / General'}">Get exact quote</button></div></aside>`;}
